#!/bin/bash
# Campus pictures for the wider set. These are regional scenes, not portraits of real landmarks: we have not checked what each campus looks like.
cd "$(dirname "$0")/../.." && export OUT_DIR="$PWD/public/art/cn"
S="A soft, warm storybook illustration in gentle pastel colours, wide 16:9, flat shapes with light texture, golden afternoon light, a few tiny students walking. No text, no letters, no logos, no emblems, no watermarks."
n=0; gen(){ [ -f "public/art/cn/$1.jpg" ] || node scripts/art/image.mjs "$1" "$S Scene: $2." > "/tmp/cn-$1.log" 2>&1 & n=$((n+1)); [ $((n % 12)) -eq 0 ] && wait; }
gen ruc "a university campus in a northern Chinese city, grey-brick teaching buildings, a traditional gate, ginkgo and pine trees"
